const jobs=[{id:'6c3e8600-1111-4b22-9c33-123456789001',shop:'Mbare Market Fresh',pickup:'12 Cripps Road, Mbare',destination:'Arcadia, Harare',parcel:'1 grocery case • handle upright',toPickup:2.3,distance:4.8,minFare:4.10,fee:4.10,status:'open',pickupLat:-17.8585,pickupLng:31.0451,dropLat:-17.8348,dropLng:31.0641},{id:'6c3e8600-1111-4b22-9c33-123456789002',shop:'BuildSmart Hardware',pickup:'Simon Mazorodze Road',destination:'Belvedere, Harare',parcel:'Small hardware parcel • 4 kg',toPickup:3.1,distance:7.2,minFare:5.90,fee:5.90,status:'bid submitted',pickupLat:-17.874,pickupLng:31.0102,dropLat:-17.8278,dropLng:31.0116},{id:'6c3e8600-1111-4b22-9c33-123456789003',shop:'TechHub ZW',pickup:'Gulf Complex, CBD',destination:'Avondale, Harare',parcel:'Sealed electronics package',toPickup:1.4,distance:5.5,minFare:4.63,fee:4.63,status:'collected',pickupLat:-17.8298,pickupLng:31.0494,dropLat:-17.795,dropLng:31.0400}];
let currentTab='dashboard';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function icons(){window.lucide?.createIcons()}function metric(icon,label,value){return `<article class="courier-metric"><span><i data-lucide="${icon}"></i></span><div><small>${label}</small><strong>${value}</strong></div></article>`}function toast(text){const t=$('#courierToast');t.textContent=text;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}
function mapsUrl(lat,lng){return `https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(`${lat},${lng}`)}`}
function distanceKm(a,b,c,d){const r=Math.PI/180,x=Math.sin((c-a)*r/2)**2+Math.cos(a*r)*Math.cos(c*r)*Math.sin((d-b)*r/2)**2;return 6371*2*Math.asin(Math.sqrt(x))}
function courierPosition(fallback){return new Promise(resolve=>navigator.geolocation.getCurrentPosition(p=>resolve({lat:p.coords.latitude,lng:p.coords.longitude}),()=>resolve(fallback),{maximumAge:60000,timeout:6000}))}
async function hydrateJobs(){const db=window.zwconnectSupabase;if(!db||!navigator.onLine)return;try{const {data:userData}=await db.auth.getUser(),user=userData?.user;if(!user)return;const {data:courier,error:courierError}=await db.from('couriers').select('id,current_latitude,current_longitude').eq('user_id',user.id).single();if(courierError)throw courierError;const position=await courierPosition(courier.current_latitude==null?null:{lat:Number(courier.current_latitude),lng:Number(courier.current_longitude)}),{data:rows,error}=await db.from('deliveries').select('id,courier_id,pickup_address,delivery_address,pickup_latitude,pickup_longitude,delivery_latitude,delivery_longitude,parcel_details,route_distance_km,courier_fee,status').in('status',['open','accepted','collected','courier_completed']).order('created_at',{ascending:false});if(error)throw error;const mapped=await Promise.all((rows||[]).map(async row=>{const {data:quote}=row.status==='open'?await db.rpc('quote_courier_fee',{target_courier:courier.id,distance_km:row.route_distance_km,destination_city:null}):{data:row.courier_fee};return{id:row.id,courierId:row.courier_id,shop:'Pickup shop',pickup:row.pickup_address,destination:row.delivery_address,parcel:row.parcel_details||'Customer parcel',toPickup:position&&Number.isFinite(position.lat)?distanceKm(position.lat,position.lng,row.pickup_latitude,row.pickup_longitude):0,distance:Number(row.route_distance_km||0),minFare:Number(quote||0),fee:Number(row.courier_fee||quote||0),status:row.status,pickupLat:row.pickup_latitude,pickupLng:row.pickup_longitude,dropLat:row.delivery_latitude,dropLng:row.delivery_longitude}}));jobs.splice(0,jobs.length,...mapped);render()}catch(error){toast(error.message||'Could not refresh delivery jobs')}}
function jobList(){return `<div class="job-list">${jobs.map(j=>`<div class="job courier-job"><span><i data-lucide="bike"></i></span><div><strong>${j.shop} → ${j.destination}</strong><small>${j.parcel}</small><small>${j.toPickup} km courier-to-shop • ${j.distance} km shop-to-customer • ${j.status}</small><nav><a href="${mapsUrl(j.pickupLat,j.pickupLng)}" target="_blank" rel="noopener"><i data-lucide="navigation"></i> Directions to shop</a><a href="${mapsUrl(j.dropLat,j.dropLng)}" target="_blank" rel="noopener"><i data-lucide="map-pinned"></i> Directions to customer</a></nav></div><div><small>Minimum fare</small><b>US$ ${j.minFare.toFixed(2)}</b>${j.status==='open'?`<button data-accept-job="${j.id}">Submit fare</button>`:''}</div></div>`).join('')}</div>`}
function renderDashboard(){$('#courierContent').innerHTML=`<div class="courier-metrics">${metric('package-check','Jobs today','8')}${metric('route','Distance','31.4 km')}${metric('circle-dollar-sign','Delivery earnings','US$ 36.80')}${metric('star','Customer rating','4.9')}</div><div class="courier-grid"><section class="courier-panel"><div class="panel-head"><div><h2>Available and active deliveries</h2><p>Only jobs within your configured service area appear.</p></div><span class="status">Available</span></div>${jobList()}</section><section class="courier-panel"><div class="panel-head"><div><h2>Rate snapshot</h2><p>Your public fee calculation</p></div></div><div class="rate-preview"><strong>US$ 2.00 base fee</strong><small>Includes 2 km, then US$ 0.75 per km. Minimum US$ 2.00, maximum 30 km.</small></div><div class="rate-preview"><strong>Active subscription</strong><small>US$ 15.00 per 30 days • access until 18 Dec 2026</small></div></section></div>`}
function renderRates(){$('#courierContent').innerHTML=`<section class="courier-panel"><div class="panel-head"><div><h2>Distance and location rates</h2><p>Set transparent customer delivery fees. The quote function enforces your maximum distance.</p></div><span class="status">Public</span></div><form id="courierRateForm" class="rate-form"><label>Rate model<select name="type"><option value="distance">Distance based</option><option value="location">Location / zone based</option><option value="hybrid">Distance + location</option></select></label><label>Base fee (USD)<input name="base" type="number" step=".01" min="0" value="2"></label><label>Distance included (km)<input name="included" type="number" step=".1" min="0" value="2"></label><label>Fee per extra km<input name="perKm" type="number" step=".01" min="0" value=".75"></label><label>Minimum fee<input name="minimum" type="number" step=".01" min="0" value="2"></label><label>Maximum distance (km)<input name="maximum" type="number" step=".1" min="1" value="30"></label><label class="wide">Location rates (optional JSON)<textarea name="locations" placeholder='{"avondale":3.50,"borrowdale":5.00}'></textarea></label><button type="submit">Save rates</button></form><div class="rate-preview"><strong id="quotePreview">Example: 6 km delivery = US$ 5.00</strong><small>ZWConnect adds the configured booking fee separately and shows the full quote before a customer confirms.</small></div></section>`}
function renderSubscription(){$('#courierContent').innerHTML=`<section class="courier-panel subscription-card"><div><span class="status">Active</span><h2>Courier platform subscription</h2><p>The administrator controls amount, duration, trial and access status. Courier billing is isolated from shop subscriptions.</p><small>Access until 18 December 2026</small></div><div><small>Every 30 days</small><b>US$ 15.00</b></div></section>`}
function render(){const titles={dashboard:'Courier dashboard',jobs:'Delivery jobs',rates:'Rates & service area',subscription:'Courier subscription',profile:'Public courier profile'};$('#courierTitle').textContent=titles[currentTab];$$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===currentTab));if(currentTab==='dashboard')renderDashboard();else if(currentTab==='jobs')$('#courierContent').innerHTML=`<section class="courier-panel"><div class="panel-head"><div><h2>Delivery job board</h2><p>Open, accepted and collected deliveries.</p></div></div>${jobList()}</section>`;else if(currentTab==='rates')renderRates();else if(currentTab==='subscription')renderSubscription();else $('#courierContent').innerHTML=`<section class="courier-panel subscription-card"><div><span class="status">Admin approved</span><h2>Swift Pedals Harare</h2><p>Tatenda Zhou • Harare • 077 310 4421</p><small>Available for bicycle deliveries up to 30 km.</small></div><i data-lucide="badge-check"></i></section>`;icons()}
function updateSync(s){const b=$('#courierSync');b.querySelector('b').textContent=!s.online?'Offline':s.syncing?'Syncing':s.locked?'Account locked':'Synced';b.querySelector('small').textContent=s.locked?`${s.pending} pending • ${s.locked} locked`:`${s.pending} pending`;b.querySelector('i').setAttribute('data-lucide',s.locked?'lock-keyhole':s.online?'cloud-check':'cloud-off');icons()}
document.addEventListener('click',async event=>{if(!event.target.closest('#courierSignOut'))return;event.preventDefault();try{await window.zwconnectSupabase?.auth.signOut({scope:'local'})}catch{}await window.ZWOffline?.setContext('public',{userId:null,email:null,shopId:null,force:true});location.href='../'},{capture:true});
document.addEventListener('DOMContentLoaded',()=>{window.ZWOffline?.setContext('courier');window.ZWOffline?.subscribe(updateSync);render();hydrateJobs();document.addEventListener('click',e=>{const tab=e.target.closest('[data-tab]');if(tab){currentTab=tab.dataset.tab;render()}const job=e.target.closest('[data-accept-job]');if(job){const j=jobs.find(x=>x.id===job.dataset.acceptJob),fare=prompt(`Minimum fare is US$ ${j.minFare.toFixed(2)}. Enter your offer.`,j.minFare.toFixed(2));if(fare===null)return;const offered=Number(fare);if(!Number.isFinite(offered)||offered<j.minFare){toast(`Fare must be at least US$ ${j.minFare.toFixed(2)}`);return}const note=prompt('Optional note for the customer','I can collect within 20 minutes.')||'';navigator.geolocation.getCurrentPosition(p=>{j.fee=offered;j.status='bid submitted';window.ZWOffline.enqueue('delivery_bid.submit',{deliveryId:j.id,offeredFee:offered,note,latitude:p.coords.latitude,longitude:p.coords.longitude},{role:'courier'});toast(`US$ ${offered.toFixed(2)} offer sent to customer`);render()},()=>toast('Enable location so the customer can see your distance to the shop'))}});document.addEventListener('submit',e=>{if(e.target.id!=='courierRateForm')return;e.preventDefault();const d=Object.fromEntries(new FormData(e.target));let locationRates={};try{locationRates=d.locations?JSON.parse(d.locations):{}}catch{toast('Location rates must be valid JSON');return}window.ZWOffline.enqueue('courier_rate.save',{rate:{rate_type:d.type,base_fee:Number(d.base),included_km:Number(d.included),per_km_fee:Number(d.perKm),minimum_fee:Number(d.minimum),maximum_distance_km:Number(d.maximum),location_rates:locationRates}},{role:'courier'});toast('Rates saved and queued for Supabase')})});
